# Правка страниц сайта под один пакет PRO 499 ₽ (27.11.2026). Запуск: python3 edit_pages.py <папка со страницами>
import sys, os, re
D = sys.argv[1]
def ed(fn, pairs):
    p = os.path.join(D, fn); s = open(p, encoding='utf-8').read(); o = s
    for a, b in pairs:
        n = s.count(a)
        if n < 1: sys.exit('FAIL %s: not found: %s' % (fn, a[:90]))
        s = s.replace(a, b)
    open(p, 'w', encoding='utf-8').write(s); print('OK', fn, len(o), '->', len(s))

